{
  "skill_name": "vss-sop-deploy",
  "evals": [
    {
      "id": 1,
      "name": "Check standard execution",
      "prompt": "Run the standard flow for vss-sop-deploy",
      "expected_output": "The skill runs the standard flow for vss-sop-deploy successfully and produces expected outputs.",
      "assertions": [
        {
          "type": "contains",
          "text": "deploy"
        },
        {
          "type": "contains",
          "text": "vss"
        },
        {
          "type": "not_contains_pattern",
          "text": "password|credential|token|secret"
        }
      ]
    },
    {
      "id": 2,
      "name": "Check custom options and parameters",
      "prompt": "Run vss-sop-deploy with custom parameters and options",
      "expected_output": "The skill applies the custom parameters and executes the vss-sop-deploy workflow accordingly.",
      "assertions": [
        {
          "type": "contains",
          "text": "sop"
        },
        {
          "type": "contains",
          "text": "docker"
        },
        {
          "type": "not_contains_pattern",
          "text": "password|credential|token|secret"
        }
      ]
    },
    {
      "id": 3,
      "name": "Check error/invalid input negative case",
      "prompt": "Run vss-sop-deploy with invalid input parameters to trigger expected error handling",
      "expected_output": "The skill gracefully rejects the invalid input or reports a clear error message.",
      "assertions": [
        {
          "type": "contains",
          "text": "error"
        },
        {
          "type": "contains",
          "text": "invalid"
        },
        {
          "type": "not_contains_pattern",
          "text": "password|credential|token|secret"
        }
      ]
    }
  ]
}
